// MarketDataServiceHandler is an implementation of the eye.v1.MarketDataService service.
type MarketDataServiceHandler interface {
	// --- Asset CRUD ---
	CreateAsset(context.Context, *connect.Request[v1.CreateAssetRequest]) (*connect.Response[v1.Asset], error)
	GetAsset(context.Context, *connect.Request[v1.GetAssetRequest]) (*connect.Response[v1.Asset], error)
	UpdateAsset(context.Context, *connect.Request[v1.UpdateAssetRequest]) (*connect.Response[v1.Asset], error)
	DeleteAsset(context.Context, *connect.Request[v1.DeleteAssetRequest]) (*connect.Response[emptypb.Empty], error)
	ListAssets(context.Context, *connect.Request[v1.ListAssetsRequest]) (*connect.Response[v1.ListAssetsResponse], error)
	// --- Asset business logic ---
	EnrichAssetData(context.Context, *connect.Request[v1.EnrichAssetDataRequest]) (*connect.Response[v1.Asset], error)
	FindSimilarAssets(context.Context, *connect.Request[v1.FindSimilarAssetsRequest]) (*connect.Response[v1.ListAssetsResponse], error)
	// Find-first asset resolution by composite identity (symbol, market, type);
	// creates the asset only when nothing matches and dry_run is false.
	FindOrCreateAsset(context.Context, *connect.Request[v1.FindOrCreateAssetRequest]) (*connect.Response[v1.FindOrCreateAssetResponse], error)
	// Set a human identity verdict on an asset (scam-filtering). A user verdict
	// is terminal: the automated scorer never overwrites it. Admin-only until
	// per-asset RBAC lands (personal-rme).
	SetAssetVerdict(context.Context, *connect.Request[v1.SetAssetVerdictRequest]) (*connect.Response[v1.Asset], error)
	// DeleteAssetExternalRef removes one binding between an asset and an external
	// identifier. Admin-only: a binding is catalogue identity, shared by everyone.
	//
	// Bindings are otherwise immutable on purpose — identity must be stable — so
	// this exists for the one case where the binding itself was the error: an
	// unknown contract bound to a real ticker before that was refused, which then
	// routes every later sync to the wrong asset and lends it a price it has no
	// claim to. Removing the ref lets the next sync resolve the contract on its
	// own merits and isolate it.
	DeleteAssetExternalRef(context.Context, *connect.Request[v1.DeleteAssetExternalRefRequest]) (*connect.Response[emptypb.Empty], error)
	// AddAssetRiskFlag attaches a situational risk to an asset (axis 2): exploit,
	// depeg, frozen transfers, deprecation, delisting, sanctions freeze.
	//
	// THE FLAG DOES NOT TOUCH THE SUM — it does not exclude the asset from any
	// valuation and does not appear in ValuationCoverage. It marks money that is
	// real and may need acting on, which is the opposite of an identity verdict.
	//
	// Admin-only, like a verdict: a flag is catalogue-wide, seen by every user.
	AddAssetRiskFlag(context.Context, *connect.Request[v1.AddAssetRiskFlagRequest]) (*connect.Response[v1.AssetRiskFlag], error)
	// DeleteAssetRiskFlag removes one flag. Admin-only. Flags are meant to be
	// removed — that is what review_at is for — so unlike a binding this carries
	// no identity consequence.
	DeleteAssetRiskFlag(context.Context, *connect.Request[v1.DeleteAssetRiskFlagRequest]) (*connect.Response[emptypb.Empty], error)
	// --- Price CRUD ---
	CreatePrice(context.Context, *connect.Request[v1.CreatePriceRequest]) (*connect.Response[v1.Price], error)
	CreatePrices(context.Context, *connect.Request[v1.CreatePricesRequest]) (*connect.Response[v1.CreatePricesResponse], error)
	GetLatestPrice(context.Context, *connect.Request[v1.GetLatestPriceRequest]) (*connect.Response[v1.Price], error)
	ListPriceHistory(context.Context, *connect.Request[v1.ListPriceHistoryRequest]) (*connect.Response[v1.ListPriceHistoryResponse], error)
	ListPricesByInterval(context.Context, *connect.Request[v1.ListPricesByIntervalRequest]) (*connect.Response[v1.ListPriceHistoryResponse], error)
	DeletePrice(context.Context, *connect.Request[v1.DeletePriceRequest]) (*connect.Response[emptypb.Empty], error)
	DeletePrices(context.Context, *connect.Request[v1.DeletePricesRequest]) (*connect.Response[emptypb.Empty], error)
	// --- Price business logic ---
	FetchExternalPrices(context.Context, *connect.Request[v1.FetchExternalPricesRequest]) (*connect.Response[v1.FetchExternalPricesResponse], error)
	// GetPricingStatus reports, for each asset asked about, what asking its price
	// sources has produced. Batched because its caller is a valuation disclosing a
	// set of unpriced positions, not a page rendering one asset.
	//
	// Assets never asked about are simply absent from the response: there is no
	// record to report, and inventing an empty one would read as "asked, nothing
	// came back", which is the opposite statement.
	GetPricingStatus(context.Context, *connect.Request[v1.GetPricingStatusRequest]) (*connect.Response[v1.GetPricingStatusResponse], error)
	// GetSweepSchedule reports when each price source is next due to be asked.
	//
	// The sweep's own summary cannot answer this. A run that asked nobody logs
	// the same "fetched=0, stored=0" as a run with nothing to ask, so an instance
	// whose whole catalogue is deferred until next Tuesday looks identical to one
	// that is perfectly up to date. The difference lives in price_fetch_attempts,
	// which until now no RPC could read: the only way to tell the two apart was a
	// psql session on the host.
	//
	// Counted live against the attempt log rather than materialised, for the same
	// reason ListUnpricedHoldings is: a second store of what is due would be a
	// second source of truth about the schedule, free to disagree with the sweep
	// it describes.
	GetSweepSchedule(context.Context, *connect.Request[v1.GetSweepScheduleRequest]) (*connect.Response[v1.GetSweepScheduleResponse], error)
	// ResetSweepSchedule forgives the back-off accrued against a price source, so
	// its assets become due again instead of waiting out a deferral earned under
	// conditions that no longer hold.
	//
	// A miss is read as "this source does not price this asset", and the schedule
	// acts on that for up to a week. Misses collected while the source was
	// unreachable, or while it was being asked for assets it never covered, say
	// nothing about the asset but are indistinguishable from misses that do —
	// so they outlive the fix that stops them, and the instance goes on deferring
	// assets the source would price today. That is the shape prod was in on
	// 2026-08-18: a correct fix, deployed, with no observable effect for days.
	//
	// This is deliberately an operator's statement, not an inference. The service
	// cannot tell a source that was unreachable from one that genuinely lists
	// nothing, so it does not guess: resetting withdraws the CONCLUSION drawn
	// from the attempt log without touching the log itself, and asserts nothing
	// about whether a price exists. The next sweep finds out.
	//
	// Paired with GetSweepSchedule on purpose — one entity, read by one RPC and
	// withdrawn by another. Folding it into FetchExternalPrices as a flag would
	// hide a schedule mutation inside a call whose name promises prices.
	ResetSweepSchedule(context.Context, *connect.Request[v1.ResetSweepScheduleRequest]) (*connect.Response[v1.ResetSweepScheduleResponse], error)
}

